using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Cosmos provider no longer supports HasIndex (throws at model validation).
        // Removed: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);

        // Breaking change 2: Discriminator property renamed from "Discriminator" to "$type".
        // Preserve compat with existing documents that use "Discriminator".
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 3: Id format changed from "EntityType|Key" to just "Key".
        // Preserve compat with existing documents that use "Blog|<key>" format.
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .HasJsonPropertyName("id");
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // Breaking change 4: Sync I/O now throws by default.
        // If sync calls (ToList, SaveChanges) must remain, opt back in.
        // Prefer migrating to async (ToListAsync / SaveChangesAsync) long-term.
        optionsBuilder.ConfigureWarnings(w =>
            w.Ignore(Microsoft.EntityFrameworkCore.Diagnostics.CoreEventId.SyncNotSupported));
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

